ALTER TABLE public.profiles ADD COLUMN family_name text NOT NULL DEFAULT '', ADD COLUMN country text NOT NULL DEFAULT '', ADD COLUMN city text NOT NULL DEFAULT '', ADD COLUMN about text NOT NULL DEFAULT '', ADD COLUMN show_on_map boolean NOT NULL DEFAULT true, ADD COLUMN processing_consent_at timestamptz;
ALTER TABLE public.profiles ADD CONSTRAINT profile_about_length CHECK(length(about)<=300);
CREATE TABLE public.map_points(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid NOT NULL REFERENCES public.families(id),user_id uuid, country text NOT NULL,city text,latitude double precision,longitude double precision,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),consent_to_publish boolean NOT NULL DEFAULT true,processing_consent_at timestamptz NOT NULL DEFAULT now(),guest_delete_token uuid NOT NULL DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,reviewed_by uuid,moderation_note text);
GRANT SELECT ON public.map_points TO authenticated;
GRANT ALL ON public.map_points TO service_role;
ALTER TABLE public.map_points ENABLE ROW LEVEL SECURITY;
CREATE POLICY map_points_private_read ON public.map_points FOR SELECT TO authenticated USING(user_id=(select auth.uid()) OR public.has_role((select auth.uid()),'admin'));
CREATE TABLE public.point_submission_limits(bucket text PRIMARY KEY, last_submission timestamptz NOT NULL);
GRANT ALL ON public.point_submission_limits TO service_role;
ALTER TABLE public.point_submission_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.claim_point_slot(_bucket text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE changed integer; BEGIN INSERT INTO public.point_submission_limits(bucket,last_submission) VALUES(_bucket,now()) ON CONFLICT(bucket) DO UPDATE SET last_submission=now() WHERE point_submission_limits.last_submission<now()-interval '60 seconds'; GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed=1; END $$;
REVOKE ALL ON FUNCTION public.claim_point_slot(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_point_slot(text) TO service_role;
CREATE TABLE public.city_geocodes(location_key text PRIMARY KEY,latitude double precision NOT NULL,longitude double precision NOT NULL);
GRANT SELECT ON public.city_geocodes TO authenticated;
GRANT ALL ON public.city_geocodes TO service_role;
ALTER TABLE public.city_geocodes ENABLE ROW LEVEL SECURITY;
CREATE POLICY city_geocodes_authenticated_read ON public.city_geocodes FOR SELECT TO authenticated USING(true);
CREATE TABLE public.registration_consents(user_id uuid PRIMARY KEY,accepted_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.registration_consents TO authenticated; GRANT ALL ON public.registration_consents TO service_role;
ALTER TABLE public.registration_consents ENABLE ROW LEVEL SECURITY;
CREATE POLICY consents_own_read ON public.registration_consents FOR SELECT TO authenticated USING(user_id=(select auth.uid()));
CREATE POLICY consents_own_insert ON public.registration_consents FOR INSERT TO authenticated WITH CHECK(user_id=(select auth.uid()));
CREATE FUNCTION public.public_map_points() RETURNS TABLE(id uuid,family_id uuid,country text,city text,latitude double precision,longitude double precision,status text,consent_to_publish boolean,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.id,m.family_id,m.country,m.city,m.latitude,m.longitude,m.status,m.consent_to_publish,m.created_at FROM public.map_points m WHERE m.status='approved' AND m.consent_to_publish AND (m.user_id IS NULL OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=m.user_id AND p.show_on_map)) $$;
REVOKE ALL ON FUNCTION public.public_map_points() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_map_points() TO anon,authenticated;
COMMENT ON TABLE public.participant_marks IS 'DEPRECATED: new submissions use map_points; retained for compatibility';
CREATE INDEX map_points_user_idx ON public.map_points(user_id); CREATE INDEX map_points_family_idx ON public.map_points(family_id); CREATE INDEX map_points_queue_idx ON public.map_points(status,created_at);